#define MOD 1000000007LL

static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

static long long gcdll(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main(void) {
    long long N;
    char S[200005];

    if (scanf("%lld", &N) != 1) return 0;
    if (scanf("%s", S) != 1) return 0;

    long long L = (long long)strlen(S);

    /* 
       Let movement rule be:
       R -> move +1, B -> move -1 on circle.
       Starting from any point, following S must end at same relative place.
       Hence net displacement after whole string must be 0 modulo N.

       If cnt1 = number of one color, cnt2 = number of the other,
       then displacement = cntR - cntB = 2*cntR - L.
       We need 2*cntR - L ≡ 0 (mod N).

       Number of colorings of N arcs for which generated string S is possible
       from every starting point equals:
       - if displacement d != 0 mod N : 0
       - else every arc coloring works consistently with all starts, so 2^g
         where g = gcd(N, L) under periodicity condition.

       For equal-length circular arcs and requirement "from every initial point",
       the valid colorings are exactly those invariant on cycles induced by
       stepping through the string length, giving 2^{gcd(N,L)}.
    */

    long long cntR = 0;
    for (long long i = 0; i < L; ++i) {
        if (S[i] == 'R' || S[i] == 'r') cntR++;
    }

    long long disp = (2 * cntR - L) % N;
    if (disp < 0) disp += N;

    if (disp != 0) {
        printf("0\n");
        return 0;
    }

    long long g = gcdll(N, L);
    printf("%lld\n", mod_pow(2, g));
    return 0;
}

