long long fib(int n, map<int,long long>& memo) {
    if (n <= 1) return n;
    if (memo.count(n)) return memo[n];
    return memo[n] = (fib(n-1, memo) + fib(n-2, memo)) % MOD;
}
int mu(int n) {
    int factors = 0; int m = n;
    for (int i = 2; i * i <= m; i++) { if (m % i == 0) { factors++; m /= i; if (m % i == 0) return 0; } }
    if (m > 1) factors++;
    return (factors % 2 == 0) ? 1 : -1;
}
