#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

// KMP prefix function
vector<int> prefix_function(const string& s) {
    int n = (int)s.size();
    vector<int> pi(n, 0);
    for (int i = 1; i < n; ++i) {
        int j = pi[i - 1];
        while (j > 0 && s[i] != s[j]) j = pi[j - 1];
        if (s[i] == s[j]) ++j;
        pi[i] = j;
    }
    return pi;
}

// Build all divisors of n
vector<int> divisors(int n) {
    vector<int> d;
    for (int i = 1; 1LL * i * i <= n; ++i) {
        if (n % i == 0) {
            d.push_back(i);
            if (i * i != n) d.push_back(n / i);
        }
    }
    sort(d.begin(), d.end());
    return d;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string S;
    cin >> N >> S;

    // Interpretation:
    // Starting from any point, traversing the N arcs clockwise gives a binary string.
    // We need the number of circular colorings such that from every starting point,
    // the generated string equals S.
    //
    // That means every rotation of the arc-color sequence must equal S.
    // Equivalently, S must be invariant under all cyclic shifts that arise from changing
    // the starting point among the N points. This forces the circle coloring to be
    // periodic, and the count reduces to the number of cyclic binary strings whose
    // every rotation can produce S.
    //
    // For a fixed S, this is possible iff S itself is periodic with some period d | N,
    // and then the coloring is determined by choosing a binary pattern on one orbit.
    //
    // The standard result for this problem is:
    // answer = sum_{d | N and S has period d} phi(N / d)
    //
    // We detect all periods of S using prefix function.

    vector<int> pi = prefix_function(S);

    // hasPeriod[d] = whether S[i] = S[i-d] for all i>=d
    vector<char> hasPeriod(N + 1, false);

    // All periods can be derived from borders of S
    int p = N - pi[N - 1];
    if (N % p == 0) {
        for (int d = p; d <= N; d += p) {
            if (N % d == 0) hasPeriod[d] = true;
        }
    } else {
        hasPeriod[N] = true;
    }

    // More generally, mark every divisor d that is a period
    auto divs = divisors(N);
    for (int d : divs) {
        bool ok = true;
        for (int i = d; i < N; ++i) {
            if (S[i] != S[i - d]) {
                ok = false;
                break;
            }
        }
        hasPeriod[d] = ok;
    }

    // Euler phi up to N
    vector<int> phi(N + 1);
    for (int i = 0; i <= N; ++i) phi[i] = i;
    for (int i = 2; i <= N; ++i) {
        if (phi[i] == i) {
            for (int j = i; j <= N; j += i) {
                phi[j] -= phi[j] / i;
            }
        }
    }

    long long ans = 0;
    for (int d : divs) {
        if (hasPeriod[d]) {
            ans += phi[N / d];
            if (ans >= MOD) ans %= MOD;
        }
    }

    cout << ans % MOD << '\n';
    return 0;
}

